import crypto from "crypto";
import fs from "fs";
import path from "path";
import { readDb, writeDb, STORAGE_DIRS } from "./storage";

export interface CreateSessionOptions {
  title: string;
  hostId: string;
  hostName: string;
  quality?: "720p" | "1080p" | "4k";
  audioFormat?: "wav_uncompressed" | "aac_high";
}

// Strict shapes for ids that end up in file paths (generated by createSession / joinSession).
const SESSION_ID_RE = /^sess_[A-Za-z0-9_]{1,64}$/;
const PARTICIPANT_ID_RE = /^p_[A-Za-z0-9_]{1,64}$/;
const ALLOWED_CHUNK_EXTS = new Set([".webm", ".mp4", ".ogg", ".wav", ".m4a"]);
export const MAX_CHUNK_INDEX = 20000; // 3-second chunks => ~16 hours per participant

export class PodcastError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export class PodcastService {
  constructor() {
    this.ensurePodcastDir();
  }

  private ensurePodcastDir() {
    if (!fs.existsSync(STORAGE_DIRS.podcasts)) {
      fs.mkdirSync(STORAGE_DIRS.podcasts, { recursive: true });
    }
  }

  // List the sessions this user hosts. Guests never see the list; they open one session via its invite link.
  public listSessions(ownerId: string): any[] {
    if (!ownerId) return [];
    const db = readDb();
    return (db.podcastSessions || []).filter((s: any) => s && s.hostId === ownerId);
  }

  /** True when this signed-in user is the session's host. */
  public isHost(session: any, userId: string): boolean {
    return !!session && !!userId && session.hostId === userId;
  }

  // Get single session by ID
  public getSession(id: string): any | null {
    const db = readDb();
    const session = (db.podcastSessions || []).find((s: any) => s.id === id || s.inviteCode === id);
    return session || null;
  }

  // Create a new session
  public createSession(options: CreateSessionOptions): any {
    if (!options.hostId) throw new PodcastError(401, "Please sign in to start a session.");
    this.ensurePodcastDir();
    const db = readDb();
    const sessionId = `sess_${Date.now()}_${crypto.randomBytes(6).toString("hex")}`;
    const inviteCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const inviteUrl = `/?podcastSession=${sessionId}`;

    const hostParticipant: any = {
      id: `p_${Date.now()}_host`,
      name: options.hostName || "Host",
      role: "host",
      avatar: "",
      isMuted: false,
      isVideoOff: false,
      audioLevel: 0,
      connectionStatus: "ready",
      chunksRecorded: 0,
      chunksUploaded: 0,
      uploadPercentage: 100,
      isUploading: false,
    };

    const newSession: any = {
      id: sessionId,
      title: String(options.title || "Interview").slice(0, 120),
      hostId: options.hostId,
      hostName: options.hostName || "Host",
      inviteCode,
      inviteUrl,
      status: "setup", // setup | waiting | countdown | recording | paused | completed
      quality: options.quality || "1080p",
      audioFormat: options.audioFormat || "wav_uncompressed",
      createdAt: new Date().toISOString(),
      recordingDurationSec: 0,
      participants: [hostParticipant],
      tracks: [],
      transcript: [],
      liveSwitchEvents: [],
      activeCamera: "cam_host",
      aiClips: [],
      projectId: undefined,
    };

    if (!db.podcastSessions) {
      db.podcastSessions = [];
    }
    db.podcastSessions.unshift(newSession);
    writeDb(db);

    // Create session storage directory
    const sessionDir = path.join(STORAGE_DIRS.podcasts, sessionId);
    if (!fs.existsSync(sessionDir)) {
      fs.mkdirSync(sessionDir, { recursive: true });
    }

    return newSession;
  }

  // Guest joins session
  public joinSession(sessionId: string, guest: { name: string; avatar?: string }): any {
    const db = readDb();
    const session = (db.podcastSessions || []).find((s: any) => s.id === sessionId || s.inviteCode === sessionId);
    if (!session) {
      throw new Error("Session not found");
    }

    const guestName = String(guest.name || "Guest").replace(/[\u0000-\u001f]/g, "").trim().slice(0, 60) || "Guest";
    let existingGuest = session.participants.find((p: any) => p.role === "guest" && p.name === guestName);
    if (!existingGuest) {
      if (session.participants.filter((p: any) => p.role === "guest").length >= 8) {
        throw new Error("This session is full.");
      }
      existingGuest = {
        id: `p_${Date.now()}_${crypto.randomBytes(4).toString("hex")}_guest`,
        name: guestName,
        role: "guest",
        avatar: "",
        isMuted: false,
        isVideoOff: false,
        audioLevel: 0,
        connectionStatus: "connected",
        chunksRecorded: 0,
        chunksUploaded: 0,
        uploadPercentage: 100,
        isUploading: false,
      };
      session.participants.push(existingGuest);
    } else {
      existingGuest.connectionStatus = "connected";
    }

    writeDb(db);
    return { session, participant: existingGuest };
  }

  // Update session status (e.g. recording started / stopped)
  public updateStatus(sessionId: string, status: string, durationSec?: number): any {
    const db = readDb();
    const session = (db.podcastSessions || []).find((s: any) => s.id === sessionId);
    if (!session) {
      throw new Error("Session not found");
    }

    session.status = status;
    if (typeof durationSec === "number") {
      session.recordingDurationSec = durationSec;
    }
    if (status === "recording" && !session.startedAt) {
      session.startedAt = new Date().toISOString();
    }
    if (status === "completed" && !session.endedAt) {
      session.endedAt = new Date().toISOString();
    }

    writeDb(db);
    return session;
  }

  // Record live camera switch event during session
  public recordLiveSwitch(
    sessionId: string,
    switchEvent: {
      camera: "cam_host" | "cam_guest" | "cam_guest_2" | "cam_split" | "cam_gallery";
      label?: string;
      speakerName?: string;
      timestamp: number;
      transition?: "cut" | "dissolve";
    }
  ): any {
    const db = readDb();
    const session = (db.podcastSessions || []).find((s: any) => s.id === sessionId);
    if (!session) {
      throw new Error("Session not found");
    }

    if (!session.liveSwitchEvents) {
      session.liveSwitchEvents = [];
    }

    const host = session.participants.find((p: any) => p.role === "host") || { name: "Host" };
    const guest = session.participants.find((p: any) => p.role === "guest") || { name: "Remote Guest" };

    const eventRecord = {
      id: `sw_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      timestamp: Number((switchEvent.timestamp || 0).toFixed(2)),
      camera: switchEvent.camera,
      label: switchEvent.label || (
        switchEvent.camera === "cam_host"
          ? `${host.name} (Cam 1)`
          : switchEvent.camera === "cam_guest"
          ? `${guest.name} (Cam 2)`
          : switchEvent.camera === "cam_split"
          ? "Split Dual Cam"
          : "Studio Gallery"
      ),
      speakerName: switchEvent.speakerName || (switchEvent.camera === "cam_host" ? host.name : guest.name),
      transition: switchEvent.transition || "cut",
    };

    session.liveSwitchEvents.push(eventRecord);
    session.activeCamera = switchEvent.camera;
    writeDb(db);
    return { session, event: eventRecord };
  }

  // Save an uploaded chunk from local double-ender recording.
  // Every path segment is validated so a chunk can only ever land in its own participant folder.
  public saveChunk(
    sessionId: string,
    participantId: string,
    trackType: string,
    chunkIndex: number,
    buffer: Buffer,
    ext: string = ".webm"
  ): { success: boolean; chunkPath: string; chunksUploaded: number } {
    if (typeof sessionId !== "string" || !SESSION_ID_RE.test(sessionId)) {
      throw new PodcastError(400, "Invalid session id.");
    }
    if (typeof participantId !== "string" || !PARTICIPANT_ID_RE.test(participantId)) {
      throw new PodcastError(400, "Invalid participant id.");
    }
    if (trackType !== "video" && trackType !== "audio") {
      throw new PodcastError(400, "Invalid track type.");
    }
    if (!Number.isInteger(chunkIndex) || chunkIndex < 0 || chunkIndex > MAX_CHUNK_INDEX) {
      throw new PodcastError(400, "Invalid chunk index.");
    }
    const safeExt = String(ext || ".webm").toLowerCase();
    if (!ALLOWED_CHUNK_EXTS.has(safeExt)) {
      throw new PodcastError(400, "Invalid chunk file type.");
    }

    const db = readDb();
    const session = (db.podcastSessions || []).find((s: any) => s.id === sessionId);
    if (!session) throw new PodcastError(404, "Session not found");
    const participant = (session.participants || []).find((p: any) => p.id === participantId);
    if (!participant) throw new PodcastError(403, "That participant isn't part of this session.");

    const podcastsRoot = path.resolve(STORAGE_DIRS.podcasts);
    const sessionRoot = path.resolve(podcastsRoot, sessionId);
    const participantDir = path.resolve(sessionRoot, participantId);
    const chunkFileName = `${trackType}_chunk_${chunkIndex}${safeExt}`;
    const chunkFile = path.resolve(participantDir, chunkFileName);
    if (
      !sessionRoot.startsWith(podcastsRoot + path.sep) ||
      !participantDir.startsWith(sessionRoot + path.sep) ||
      path.dirname(chunkFile) !== participantDir
    ) {
      throw new PodcastError(400, "Invalid chunk path.");
    }

    fs.mkdirSync(participantDir, { recursive: true });
    fs.writeFileSync(chunkFile, buffer);

    participant.chunksUploaded = Math.max(participant.chunksUploaded || 0, chunkIndex + 1);
    participant.chunksRecorded = Math.max(participant.chunksRecorded || 0, chunkIndex + 1);
    participant.uploadPercentage = Math.min(100, Math.round((participant.chunksUploaded / Math.max(1, participant.chunksRecorded)) * 100));
    participant.isUploading = participant.uploadPercentage < 100;
    writeDb(db);

    return {
      success: true,
      chunkPath: `/storage/podcasts/${sessionId}/${participantId}/${chunkFileName}`,
      chunksUploaded: participant.chunksUploaded,
    };
  }

  // Assembling the uploaded chunks into a multitrack editor project (plus transcript and AI clips)
  // isn't built yet. The route answers 501; this never invents tracks, transcripts or clips.
  public finalizeSession(_sessionId: string, _incomingLiveSwitches?: any[]): never {
    throw new PodcastError(501, "Podcast recording export isn't available yet.");
  }
}

export const podcastService = new PodcastService();
